SELLM_STRICT=1 uv run python - <<'EOF' 2>&1 | cut -c1-330
import os, json
from arena_kit.cli import load_env; load_env()
from arena_kit.data import DataPackage
from arena_kit.cost import total_cost, score
from arena_kit.client import ArenaError
from sellm.agent import make_agent
from sellm.lab import stress
from sellm.lab.table import LocalTable, play_lab
pkg = DataPackage("data/package"); pkg.lookup("")
scen = {s.name: s for s in stress.pools(pkg)}
for name in ("X71-001", "X71-002"):
    s = scen[name]; case = s.case; b = case["buyer"]; alt = b.get("alternative") or {}
    print(f"\n== {name} {s.tags} type {case['type']} goal {b['category_goal']} | C_open {s.c_open:,.0f} C_best {s.c_best:,.0f} scenario c_alt {s.c_alt:,.0f} | alt kind {alt.get('kind')} terms {alt.get('terms')}")
    print("   my c_alt:", f"{total_cost(case, alt['terms']):,.0f}" if (alt.get('terms') or {}).get('unit_price') else None, "| negotiable", case["negotiable"], "| H", b["horizon_years"], "need", b["need_per_year"], "fallback", b["fallback_unit_price"])
    table = LocalTable(s, pkg.facts, seed=0, clock=True, wave_cap_s=480, think_s=2.0, package=pkg)
    r = play_lab(table, make_agent(pkg), mode="parallel")
    print("   result:", r.get("end_reason"), "score", r["score"], "c_deal", r.get("c_deal"), "terms", {k: (r.get("terms") or {}).get(k) for k in case["negotiable"]})
for name in ("X76-002", "X07-083"):
    s = scen[name]
    for seed in (0, 1):
        table = LocalTable(s, pkg.facts, seed=seed, clock=True, wave_cap_s=480, think_s=2.0, package=pkg)
        try:
            r = play_lab(table, make_agent(pkg), mode="parallel", strict=True)
            print(f"\n== {name} seed {seed}: no refusal, score {r['score']:.2f}, timeouts {r.get('timeouts')}")
        except ArenaError as e:
            print(f"\n== {name} seed {seed} REFUSED: {e}")
            for sid, t in table.threads.items():
                print("   ", sid, [(m.get("from", "?")[:8], m.get("status"), [ (x.get("term_sheet_id"), x["terms"]) for x in (m.get("term_sheets") or [])][:1]) for m in t.messages][-4:])
EOF

